// Below-average quality-ranking digest - tune here.
return [{ json: {
  DATE_PRESET: 'last_7d',   // MUST be a short window: quality_ranking
                          // returns UNKNOWN on last_30d, verified on a
                          // 465-ad account incl. ads with 550k impressions
  MIN_SPEND: 20,   // only flag ads that spent at least this
} }];

const cfg = $('Set config: quality digest').first().json;
const rows = $json.data || [];
const isLow = (v) => typeof v === 'string' && v.indexOf('BELOW_AVERAGE') === 0;
const flagged = [];
for (const r of rows) {
  const spend = Number(r.spend)||0;
  if (spend < cfg.MIN_SPEND) continue;
  const low = [];
  if (isLow(r.quality_ranking)) low.push('quality');
  if (isLow(r.engagement_rate_ranking)) low.push('engagement');
  if (isLow(r.conversion_rate_ranking)) low.push('conversion');
  if (!low.length) continue;
  flagged.push({ ad: r.ad_name, campaign: r.campaign_name, adset: r.adset_name, spend:+spend.toFixed(2),
    quality: r.quality_ranking||'UNKNOWN', engagement: r.engagement_rate_ranking||'UNKNOWN', conversion: r.conversion_rate_ranking||'UNKNOWN', below_on: low });
}
flagged.sort((a,b)=> b.spend-a.spend);
return [{ json: { date_preset: cfg.DATE_PRESET, flagged_count: flagged.length, spend_at_risk: +flagged.reduce((n,f)=>n+f.spend,0).toFixed(2), flagged } }];

const d = $json;
const system = 'You are a Meta creative strategist. Meta rates each ad below/average/above average on quality, engagement-rate and conversion-rate ranking. Below-average quality points to the creative, engagement to the hook/relevance, conversion to the offer/landing page. For each flagged ad give the most likely lever and one fix. Be terse. Return ONLY valid JSON, no prose, no markdown fences.';
const user = 'Ads spending with a below-average ranking (worst-spend first):\n' + JSON.stringify(d.flagged.slice(0,20)) + '\n\nReturn JSON exactly: {"summary":"one sentence","fixes":[{"ad":"","below_on":"","lever":"","fix":""}]}';
const body = { model:'gpt-4o-mini', max_tokens:3000, response_format:{type:'json_object'},
  messages:[{role:'system',content:system},{role:'user',content:user}] };
return [{ json: { body, _ctx: d } }];

const ctx = $('Build AI quality prompt').first().json._ctx || {};
function aiJson(fallback){ const t=($json.choices&&$json.choices[0]&&$json.choices[0].message&&$json.choices[0].message.content)||''; let s=String(t).trim().replace(/^```(?:json)?/i,'').replace(/```$/,'').trim(); try{return JSON.parse(s)}catch(e){} const m=s.match(/\{[\s\S]*\}/); if(m){try{return JSON.parse(m[0])}catch(e){}} return fallback; }
const ai = aiJson({ summary:'AI response could not be parsed.', fixes:[] });
const lines=[];
lines.push('META QUALITY-RANKING DIGEST (' + (ctx.date_preset||'') + ')');
lines.push('Below-average ads: ' + (ctx.flagged_count||0) + ' | Spend at risk: $' + (ctx.spend_at_risk||0));
lines.push('');
lines.push(ai.summary||'');
for (const f of (ai.fixes||[])) { lines.push('- ' + f.ad + ' [' + f.below_on + ' -> ' + (f.lever||'') + ']'); if (f.fix) lines.push('    ' + f.fix); }
return [{ json: { report: lines.join('\n'), context: ctx, ai } }];
